/* =====================================================================
   LOGO LDMprint (immagine dell'azienda, sfondo trasparente)
   ===================================================================== */
const LOGO_SRC = 'data:image/webp;base64,';
const LOGO_AR = 768/653;
const logoImg = new Image();
const logoWaiting = [];
const onLogo = fn => { if (logoImg.complete && logoImg.naturalWidth) fn(); else logoWaiting.push(fn); };
logoImg.onload = () => { logoWaiting.splice(0).forEach(f=>{ try { f(); } catch(e){ console.warn(e); } }); };
logoImg.src = LOGO_SRC;
const logoTex = new THREE.Texture(logoImg);
logoTex.anisotropy = MAX_ANI;
onLogo(()=>{ logoTex.needsUpdate = true; });
// materiale per il logo stampato sulle magliette (compare quando l'immagine è pronta)
const LOGO_DECAL_MAT = new THREE.MeshStandardMaterial({transparent:true, opacity:0, roughness:.85, depthWrite:false,
  polygonOffset:true, polygonOffsetFactor:-4, polygonOffsetUnits:-4});
onLogo(()=>{ LOGO_DECAL_MAT.map = logoTex; LOGO_DECAL_MAT.opacity = 1; LOGO_DECAL_MAT.needsUpdate = true; });
document.documentElement.style.setProperty('--logo', `url("${LOGO_SRC}")`);
{ const sl = document.getElementById('startlogo'); if (sl) sl.src = LOGO_SRC; }

// scatole di cartone col logo (tavolo imballaggio e pacchi trasportati)
const boxC = mkCanvas(256,256);
function drawBoxTex(){
  const g = boxC.getContext('2d');
  g.fillStyle = '#c79d63'; g.fillRect(0,0,256,256);
  for (let i=0;i<2600;i++){ g.fillStyle = `rgba(${TR()<.5?'90,60,25':'255,235,200'},${TR()*.12})`; g.fillRect(TR()*256|0, TR()*256|0, 2, 2); }
  g.fillStyle = 'rgba(120,85,40,.25)'; g.fillRect(0,0,256,4); g.fillRect(0,252,256,4); g.fillRect(0,0,4,256); g.fillRect(252,0,4,256);
  g.fillStyle = 'rgba(235,222,190,.85)'; g.fillRect(0,20,256,30);                       // nastro adesivo
  g.fillStyle = 'rgba(255,255,255,.25)'; g.fillRect(0,24,256,4);
  if (logoImg.naturalWidth){ const h = 120, w = h*LOGO_AR; g.drawImage(logoImg, (256-w)/2, 78, w, h); }
  g.fillStyle = '#1d2c52'; g.font = 'bold 22px sans-serif'; g.textAlign = 'center'; g.fillText('LDMprint', 128, 232);
  TX.box && (TX.box.needsUpdate = true);
}
drawBoxTex();
TX.box = new THREE.CanvasTexture(boxC); TX.box.anisotropy = MAX_ANI;
onLogo(drawBoxTex);
MAT.cardboard.map = TX.box; MAT.cardboard.needsUpdate = true;

// schermo del computer: desktop "LDMprint OS"
function drawScreen(){
  scrC.width = 256; scrC.height = 160;
  const g = scrC.getContext('2d');
  const gr = g.createLinearGradient(0,0,256,160); gr.addColorStop(0,'#0c1830'); gr.addColorStop(1,'#1f3d70');
  g.fillStyle = gr; g.fillRect(0,0,256,160);
  g.fillStyle = '#10151d'; g.fillRect(0,0,256,20);
  g.fillStyle = '#e8ecf4'; g.font = 'bold 13px sans-serif'; g.textBaseline = 'middle'; g.fillText('LDMprint OS', 26, 10);
  if (logoImg.naturalWidth){
    g.drawImage(logoImg, 4, 2, 19, 16);
    const h = 92, w = h*LOGO_AR; g.drawImage(logoImg, (256-w)/2, 30, w, h);
  }
  g.fillStyle = 'rgba(0,0,0,.45)'; g.fillRect(0,140,256,20);
  ['#ff8a1f','#2ec4b6','#6c8fd8','#f1f2f6'].forEach((c,i)=>{ g.fillStyle = c; g.fillRect(8 + i*20, 144, 12, 12); });
  TX.screen.magFilter = THREE.LinearFilter; TX.screen.minFilter = THREE.LinearFilter;
  TX.screen.needsUpdate = true;
}
drawScreen(); onLogo(drawScreen);

// pannello con il logo da appendere alle pareti (leggermente retroilluminato)
function logoPanel(w, h, x, y, z, ry){
  const c = mkCanvas(768, Math.round(768*h/w));
  const t = new THREE.CanvasTexture(c); t.anisotropy = MAX_ANI;
  const draw = ()=>{
    const g = c.getContext('2d'), W = c.width, H = c.height;
    const gr = g.createLinearGradient(0,0,0,H); gr.addColorStop(0,'#1a1e27'); gr.addColorStop(1,'#07080c');
    g.fillStyle = gr; g.fillRect(0,0,W,H);
    g.strokeStyle = 'rgba(110,145,215,.45)'; g.lineWidth = 5; g.strokeRect(10,10,W-20,H-20);
    if (logoImg.naturalWidth){ const lh = H*.76, lw = lh*LOGO_AR; g.drawImage(logoImg, (W-lw)/2, (H-lh)/2, lw, lh); }
    t.needsUpdate = true;
  };
  draw(); onLogo(draw);
  const face = new THREE.MeshStandardMaterial({map:t, emissive:0xffffff, emissiveMap:t, emissiveIntensity:.3, roughness:.3, metalness:.1});
  const edge = new THREE.MeshStandardMaterial({color:0x2a3346, roughness:.4, metalness:.5});
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, .07), [edge,edge,edge,edge,face,edge]);
  m.position.set(x, y, z); m.rotation.y = ry; m.castShadow = true; m.receiveShadow = true;
  scene.add(m);
  // striscia LED sotto il pannello
  const led = new THREE.Mesh(new THREE.BoxGeometry(w*.9, .025, .04), new THREE.MeshBasicMaterial({color:0x9fc0ff}));
  led.position.set(0, -h/2 - .06, .02); m.add(led);
  return m;
}

function box(w,h,d,mat,x,y,z,parent,noShadow){
  const m = new THREE.Mesh(new THREE.BoxGeometry(w,h,d), mat);
  m.position.set(x,y,z);
  if (!noShadow){ m.castShadow = true; m.receiveShadow = true; }
  (parent||scene).add(m); return m;
}
function instBlocks(list, mat){
  const mesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1), mat, list.length);
  const m = new THREE.Matrix4();
  list.forEach((p,i)=>{ m.makeTranslation(p[0]+.5, p[1]+.5, p[2]+.5); mesh.setMatrixAt(i,m); });
  mesh.castShadow = true; mesh.receiveShadow = true; mesh.frustumCulled = false;
  scene.add(mesh); return mesh;
}
